(function(){function q(s){return document.querySelectorAll(s)}function a(e){return document.querySelector(e)}function bindActionButtons(){var btns=q('button.script_action_start,button.script_action_stop');btns.forEach(function(b){b.addEventListener('click',function(ev){ev.preventDefault();if(b.disabled)return;var target=b.getAttribute('data-target');b.disabled=true;b.classList.add('is-loading');fetch(target).then(function(r){return r.text()}).then(function(res){var id=b.getAttribute('data-script');var show=document.getElementById('show_'+id);if(show)show.innerHTML=res;fetch('cgi-bin/scripts.cgi').then(function(r){return r.text()}).then(function(html){var c=document.getElementById('content');if(c)c.innerHTML=html});b.disabled=false;b.classList.remove('is-loading')})})})}function bindAutostart(){var inputs=q('input.autostart');inputs.forEach(function(i){i.addEventListener('click',function(ev){ev.preventDefault();i.disabled=true;var url=i.checked?i.getAttribute('data-checked'):i.getAttribute('data-unchecked');fetch(url).then(function(r){return r.json()}).then(function(res){i.disabled=false;if(res.status=='ok'){i.checked=!i.checked}})})})}function bindViewScript(){var links=q('a.view_script');links.forEach(function(l){l.addEventListener('click',function(ev){ev.preventDefault();var qv=document.getElementById('quickviewDefault');var v=document.getElementById('quicViewContent');if(qv.classList.contains('is-active'))qv.classList.remove('is-active');if(v) v.innerHTML='Loading...';fetch(l.getAttribute('href')).then(function(r){return r.text()}).then(function(h){if(v)v.innerHTML=h; if(qv) qv.classList.add('is-active')})})})}document.addEventListener('DOMContentLoaded',function(){bindActionButtons();bindAutostart();bindViewScript()});})();